1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
6	import {
7	  answeringOrchestrator,
8	  delegatingStore,
9	  MALFORMED_LIST_SESSIONS,
10	  stopEngines,
11	  trackClient,
12	  trackServer,
13	} from './wsTestSupport.js';
14	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
15	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
16	import {setLogger} from '../shared/logger.js';
17	
18	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
19	
20	interface Frame {
21	  type: string;
22	  sessionId?: string;
23	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
24	  code?: string;
25	  message?: string;
26	}
27	
28	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
29	
30	beforeEach(() => {
31	  logLines.length = 0;
32	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
33	    void logLines.push({level, category, message, fields});
34	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
35	});
36	
37	afterEach(async () => {
38	  await stopEngines();
39	  setLogger();
40	});
41	
42	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
43	  const hal = createServer({
44	    app: (() => undefined) as unknown as Express,
45	    wsAuth: async () => ({id: userId}),
46	    sessionStore: store,
47	    orchestrator: answeringOrchestrator,
48	  });
49	  await hal.start(0);
50	  trackServer(hal);
51	  const {port} = hal.server.address() as AddressInfo;
52	  return `ws://127.0.0.1:${port}/hal/ws`;
53	};
54	
55	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
56	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
57	  trackClient(client);
58	  const frames: Frame[] = [];
59	  let connected: Frame = {type: ''};
60	  await new Promise<void>(resolve => {
61	    client.on('message', raw => {
62	      const frame = JSON.parse(String(raw)) as Frame;
63	      if (frame.type === 'pong') {
64	        resolve();
65	        return;
66	      }
67	      if (frame.type !== 'connected') {
68	        frames.push(frame);
69	        return;
70	      }
71	      connected = frame;
72	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
73	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
74	    });
75	  });
76	  return {connected, frames};
77	};
78	
79	describe('listing conversations over the WebSocket protocol', () => {
80	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
81	    const inner = new InMemorySessionStore();
82	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
83	    const summaries: SessionSummary[] = [
84	      {
85	        sessionId: 's2',
86	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
87	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
88	        entryCount: 4,
89	      },
90	    ];
91	    const store: SessionStore = {
92	      ...delegatingStore(inner),
93	      listFor: (userId, options) => {
94	        seen.push({userId, options});
95	        return summaries;
96	      },
97	    };
98	    const url = await startEngine(store, 'u1');
99	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
100	
101	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
102	
103	    expect({seen, frames}).toEqual({
104	      seen: [{userId: 'u1', options: {limit: 10, before}}],
105	      frames: [
106	        {
107	          type: 'session_list',
108	          sessions: [
109	            {
110	              sessionId: 's2',
