4	import {v4 as uuidv4} from 'uuid';
5	import type {WsAuthenticator} from '../../types/auth.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import type {ConnectedMessage} from '../../types/messages.js';
8	import type {AuthenticatedUser, ChatSession} from '../../types/session.js';
9	import {ErrorCodes} from '../../types/session.js';
10	import {sendError} from './sender.js';
11	import {isUserMessageFrame} from './messageHandler.js';
12	import {isValidWsPath, rejectSocket, parseWsData, sessionIdFromUpgrade, newSessionRequested} from './helpers.js';
13	import {credentialFromSubprotocol} from './subprotocol.js';
14	import {replayEntries, resumableSession, resumeFields} from './sessionResume.js';
15	import type {ConnectInfo, SessionResumeOptions} from './sessionResume.js';
16	import {log} from '../../shared/logger.js';
17	
18	export interface ExtWebSocket extends WebSocket {
19	  isAlive: boolean;
20	  userId: string | number;
21	  workspaceId?: string | number;
22	  authHeaders?: {
23	    cookie?: string;
24	    authorization?: string;
25	    host?: string;
26	  };
27	  requestedSessionId?: string;
28	  startNewSession?: boolean;
29	}
30	
31	export interface ConnectionHandlerDeps {
32	  wsAuth: WsAuthenticator;
33	  sessionStore: SessionStore;
34	  /** `signal` is the connection's own, aborted when its socket closes (specs/hal-engine-abandon-on-close/spec.md). */
35	  handleMessage: (
36	    ws: WebSocket,
37	    session: import('../../types/session.js').ChatSession,
38	    rawMessage: unknown,
39	    signal?: AbortSignal
40	  ) => Promise<void>;
41	  basePath: string;
42	  onConnect?: (session: import('../../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
43	  onDisconnect?: (sessionId: string) => void | Promise<void>;
44	  resume?: SessionResumeOptions;
45	}
46	export function createUpgradeHandler(wss: WebSocketServer, deps: ConnectionHandlerDeps) {
47	  return function handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer): void {
48	    // Nothing may throw out of this listener: the `upgrade` event has no catch above it, so a throw ends the process.
49	    if (!request.headers.host || !isValidWsPath(request.url || '', deps.basePath)) {
50	      rejectSocket(socket, '400 Bad Request');
51	      return;
52	    }
53	
54	    authenticate(deps.wsAuth, request)
55	      .then(user => {
56	        if (!user) {
57	          rejectSocket(socket, '401 Unauthorized');
58	          return;
59	        }
60	
61	        wss.handleUpgrade(request, socket, head, ws => {
62	          const extWs = ws as ExtWebSocket;
63	          extWs.userId = user.id;
64	          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
65	          extWs.authHeaders = {
66	            cookie: request.headers.cookie,
67	            authorization: request.headers.authorization || bearerFromWebSocketProtocol(request),
68	            host: (request.headers['x-forwarded-host'] as string | undefined) ?? request.headers.host,
69	          };
70	          extWs.isAlive = true;
71	          if (deps.resume?.enabled) {
72	            extWs.requestedSessionId = sessionIdFromUpgrade(request.url || '', deps.basePath);
73	            extWs.startNewSession = newSessionRequested(request.url || '', deps.basePath);
74	          }
75	          wss.emit('connection', extWs, request);
76	        });
77	      })
