231	function processChunk(
232	  ws: WebSocket,
233	  session: ChatSession,
234	  state: StreamState,
235	  parser: ThinkingTagParser,
236	  chunk: MessageChunk
237	): void {
238	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
239	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
